import{z as B,x as d,o as E,c as i,q as p,j as A,D as r,d as l,s as n,S as t,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"SADP / SAQP 自对准双重/四重图形","description":"","frontmatter":{"title":"SADP / SAQP 自对准双重/四重图形","date":"2026-09-03T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/sadp-saqp.md","filePath":"litho/sadp-saqp.md","lastUpdated":1791063341000}'),o={name:"litho/sadp-saqp.md"};function D(c,a,m,P,S,h){const s=d("Mermaid");return E(),i("div",null,[a[2]||(a[2]=p('<h1 id="sadp-saqp-自对准双重-四重图形" tabindex="-1">SADP / SAQP 自对准双重/四重图形 <a class="header-anchor" href="#sadp-saqp-自对准双重-四重图形" aria-label="Permalink to &quot;SADP / SAQP 自对准双重/四重图形&quot;">​</a></h1><div class="epigraph"><p>自对准双重图形用薄膜侧墙把节距对半劈开：线宽由沉积厚度定义，成对线条之间不依赖第二次光刻的套刻。</p><footer>—— 归纳自 spacer-defined double patterning 的标准工艺逻辑；分辨率极限仍受 Mack 单次曝光 $k_1$ 约束于 mandrel</footer></div><p><a href="/litho/lelele-triple">上一课</a>（LELELE）。LELE 把相邻线分给两张掩模，靠套刻把它们拼回目标节距。自对准双重图形（SADP）走另一条路：一次光刻只做出较疏的 mandrel（芯轴），在侧壁沉积 spacer，去掉 mandrel 后，留下的 spacer 环（再切开）成为节距减半的线条。线宽由原子层沉积一类薄膜的厚度决定，均匀性可以优于空中像阈值切割。再做一轮 spacer，就是 SAQP（自对准四重），节距再近乎减半。本篇讲自对准的含义、一维偏好，以及切线层如何把套刻请回来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>浸没单次曝光对 mandrel 仍要满足 \\(k_1\\ge 0.25\\) 量级。若目标线节距是 mandrel 节距的一半，SADP 把光学负担留在疏一倍的芯轴上，密线负担交给薄膜。问题是：spacer 形成的是围绕 mandrel 的闭合环，要变成逻辑或存储器用的线栅，必须切开（cut）或用后续刻蚀丢掉不需要的边。切的位置是另一次光刻，与鳍、栅或金属的套刻重新成为一阶。SADP 不是「这一层再也不需要对准」。</p><p><span class="marginnote">术语翻译：mandrel（芯轴）是先用光刻做出的「骨架」；spacer（侧墙）是贴在骨架侧壁的薄膜。骨架拆掉后，两侧墙留下来当新图形——相当于用一次光刻换出两倍密度的线。</span></p><p>二维拐角、T 型结、任意宽度的金属，spacer 几何很难自然生成。SADP 擅长固定节距的一维栅（鳍、某些金属），不擅长任意二维布线。把全芯片金属都说成 SAQP，通常是宣传而不是布局事实。</p><h3 id="mandrel-光刻仍是普通-duv" tabindex="-1">Mandrel 光刻仍是普通 DUV <a class="header-anchor" href="#mandrel-光刻仍是普通-duv" aria-label="Permalink to &quot;Mandrel 光刻仍是普通 DUV&quot;">​</a></h3><p>芯轴要用 <a href="/litho/arf-immersion">ArF 浸没</a> 加上 OAI/OPC 印出来，CD 与线边粗糙度会传到 spacer 位置：mandrel 宽度误差改变两根 spacer 之间的芯轴侧间距，但不以 LELE 那种方式把两根 spacer 相对滑开——两根 spacer 仍贴在同一芯轴的两侧。这就是「自对准」：成对线的内间距由 mandrel CD 与 spacer 厚度决定，不由第二次线层曝光的 overlay 决定。外间距（相邻 mandrel 之间）则吃 mandrel 光刻的 CD 与节距均匀性。</p><p><span class="marginnote">SADP 之后会出现两种间隔：芯轴侧（core）与间隙侧（gap/space），往往统计上不完全相等。电性与刻蚀要分别标定。不要假设节距减半后所有 space 同一分布。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>典型正 spacer 流程：光刻与刻蚀 mandrel → 保形沉积 spacer 材料（常 ALD）→ 各向异性回刻，只留侧墙 → 去掉 mandrel → 以 spacer 为掩模往下刻硬掩模或衬底。负 spacer / 反相方案改变谁留下，几何思想相同。SAQP：在第一轮 spacer 图形上再做 mandrel 或直接再长 spacer，把节距再劈一次。每一轮薄膜厚度都进入最终 CD。切线掩模（cut mask）用另一次光刻在选定位置打断线，或先切 mandrel 再长 spacer（方案多种）。</p><p>与 LELE 的对照：SADP 增加的是沉积与回刻模块，而不是第二次线层曝光。扫描机次数：mandrel 一次 + 每次切线一次，通常少于同等密度的 LELE 线层次数，但刻蚀与薄膜步骤更多。产能账要按模块算，不能只数光刻。</p><h3 id="saqp-把均匀性要求转到薄膜" tabindex="-1">SAQP 把均匀性要求转到薄膜 <a class="header-anchor" href="#saqp-把均匀性要求转到薄膜" aria-label="Permalink to &quot;SAQP 把均匀性要求转到薄膜&quot;">​</a></h3><p>四重之后，最终半节距大约是 mandrel 半节距的四分之一（在理想一维图里）。光学 \\(k_1\\) 仍只约束 mandrel。薄膜厚度的晶圆内均匀性、加载效应与微负载，变成 CD 均匀性的主源。原子层沉积的逐圈控制是 SAQP 能进鳍工艺的原因之一。Mack 的瑞利公式在这里不再直接给出最终鳍宽——鳍宽是 spacer 厚度经刻蚀转移后的结果。</p><p><span class="marginnote">数字实例：mandrel 节距 80 nm、spacer 每侧长 15 nm 上下时，SADP 后线节距约 40 nm；再做一轮 spacer（SAQP）就逼近 20 nm。每轮「减半」的魔法都来自那层 ALD 薄膜的厚度，而不是镜头更强。</span></p>',16)),(E(),A(t,null,{default:r(()=>[n(s,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22Mandrel%20%E5%85%89%E5%88%BB%2B%E5%88%BB%E8%9A%80%22%5D%20--%3E%20SP%5B%22%E4%BF%9D%E5%BD%A2%E6%B2%89%E7%A7%AF%20spacer%22%5D%0A%20%20SP%20--%3E%20ET%5B%22%E5%90%84%E5%90%91%E5%BC%82%E6%80%A7%E5%9B%9E%E5%88%BB%22%5D%0A%20%20ET%20--%3E%20RM%5B%22%E5%8E%BB%E6%8E%89%20mandrel%22%5D%0A%20%20RM%20--%3E%20CUT%5B%22%E5%88%87%E7%BA%BF%E5%85%89%E5%88%BB%20%E5%8F%AF%E9%80%89%22%5D%0A%20%20CUT%20--%3E%20TR%5B%22%E8%BD%AC%E5%8D%B0%E5%88%B0%E8%A1%AC%E5%BA%95%22%5D%0A%20%20RM%20--%3E%20Q%5B%22%E5%86%8D%E4%B8%80%E8%BD%AE%20spacer%20%3D%20SAQP%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"自对准的几何：spacer 的内边缘贴着 mandrel 侧壁。两次曝光之间的相对平移不会把左 spacer 和右 spacer 拆开，因为没有第二次「线」曝光。LELE 的 \\(\\delta\\) 在这一对线上不出现。Mandrel 的 overlay 仍然决定整组线栅相对有源区或浅槽隔离落在哪里——那是层间套刻，不是对内半节距。切线若要对准到栅或接触，overlay 回到切线层。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：SADP 定线宽不再问镜头，而是问薄膜——好比裁缝不用画粉线（光刻）定边，而是靠贴边的胶带厚度（spacer）定边；胶带贴得多匀，衣边就有多准。")],-1)),(E(),A(t,null,{default:r(()=>[n(s,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20LR%0A%20%20LELE%5B%22LELE%3A%20%E4%B8%A4%E6%9D%A1%E7%BA%BF%E6%9D%A5%E8%87%AA%E4%B8%A4%E6%AC%A1%E6%9B%9D%E5%85%89%22%5D%20--%3E%20DELTA%5B%22%E5%A5%97%E5%88%BB%E8%AF%AF%E5%B7%AE%20%CE%B4%20%E6%8B%89%E5%BC%80%E4%B8%A4%E6%9D%A1%E7%BA%BF%22%5D%0A%20%20DELTA%20--%3E%20BADCD%5B%22%E5%86%85%E9%97%B4%E8%B7%9D%E7%9B%B4%E6%8E%A5%E5%8F%98%E5%B7%AE%22%5D%0A%20%20SADP%5B%22SADP%3A%20%E4%B8%A4%E6%A0%B9%20spacer%20%E9%95%BF%E5%9C%A8%E5%90%8C%E4%B8%80%E8%8A%AF%E8%BD%B4%E4%B8%A4%E4%BE%A7%22%5D%20--%3E%20FIX%5B%22%E5%86%85%E9%97%B4%E8%B7%9D%20%3D%20%E8%8A%AF%E8%BD%B4CD%20%2B%202%C3%97spacer%E5%8E%9A%22%5D%0A%20%20FIX%20--%3E%20SAFE%5B%22%E7%BA%BF%E5%B1%82%E5%A5%97%E5%88%BB%E8%AF%AF%E5%B7%AE%E8%BF%9B%E4%B8%8D%E4%BA%86%E5%86%85%E9%97%B4%E8%B7%9D%22%5D%0A%20%20CUT%5B%22%E5%88%87%E7%BA%BF%E5%B1%82%E4%BB%8D%E8%A6%81%E5%A5%97%E5%88%BB%22%5D%20--%3E%20GRID%5B%22%E5%86%B3%E5%AE%9A%E6%95%B4%E7%BB%84%E7%BA%BF%E6%A0%85%E8%90%BD%E7%82%B9%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=p('<p>线端与环的处理消耗设计规则：线不能任意终止，必须在允许切的栅格上切。这就是为什么标准单元和鳍工艺愿意改布局去迁就 SADP，而随机金属层更常留在 LELE 或 EUV。SAQP 的线端与多重 spacer 的「哪一轮定义哪条边」更绕，设计规则更长。</p><p><span class="marginnote">「自对准」不是「无套刻」。它只免除成对 spacer 之间的线层套刻。层间、切线、通孔仍然要套。把 SADP 写成可以放松扫描机 overlay 规格到微米级，是错的。</span></p><h3 id="与-lele-共存" tabindex="-1">与 LELE 共存 <a class="header-anchor" href="#与-lele-共存" aria-label="Permalink to &quot;与 LELE 共存&quot;">​</a></h3><p>同一商品节点里，鳍或某一维金属走 SAQP，切栅、通孔、二维局部互连走 LELE 或 EUV，是常见分工。比较「谁更先进」没有意义；比较的是拓扑与误差源。LELE 误差源是 overlay；SADP 误差源是薄膜与 mandrel CD。两者都会叠加到最终电性，但 knobs 不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>SADP/SAQP 增加工艺模块、缺陷机会（spacer 掉落、残留、微桥）和周期时间。掩模张数不一定少：切线、通孔、填充仍要掩模。EUV 插入后，部分原 SAQP 层改为 EUV 单次，是为了缩短周期与简化 2D，不是因为 spacer 物理失效。浸没 DUV 仍可给 mandrel 与大量切线层供货。</p><p>不要用 SADP「等效 \\(k_1\\)」去倒推良率。等效 \\(k_1\\) 只是把最终半节距代回瑞利公式的一种说法，薄膜误差不在 \\(k_1\\) 里。本篇不提供 7 nm / 5 nm 的成品率数字。公开文献讨论过逻辑鳍用 SAQP、金属用 LELE 或 EUV 的组合，那是图形策略，不是良率表。</p><p><span class="marginnote">spacer 材料与衬底的刻蚀选择比必须足够高，否则转印时 CD 漂移，自对准的几何优势被刻蚀偏置吃掉。这是<a href="/litho/litho-process-flow">工艺链</a>最后一段的事。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SADP 用 mandrel + spacer 把节距减半；线宽由薄膜厚度定义，成对线自对准。</li><li>SAQP 再做一轮 spacer，理想一维下节距再近乎减半。</li><li>Mandrel 光刻仍受单次 \\(k_1\\) 限制；最终 CD 主要吃薄膜与刻蚀。</li><li>切线、层间对准仍要光刻套刻；「自对准」范围仅限 spacer 对。</li><li>拓扑偏一维栅；任意二维金属通常不是 SADP 的主场。</li><li>与 LELE 按误差源和图形类型分工，而不是互相完全替代。</li><li>出处：Mack 对单次曝光极限与多重图形动机的论述；spacer DP 的标准工艺描述（与 ASML 多重图形/浸没公开语境一致）。</li></ul>',10))])}const f=B(o,[["render",D]]);export{u as __pageData,f as default};
